def print_grid(grid):
    """Print the given grid in a readable format."""
    for row in grid:
        print(' | '.join(row))
        print(' ---------')

def is_valid_move(grid, move):
    """Check if the given move is valid."""
    row, col = move.split()
    row, col = int(row) - 1, int(col) - 1  # Subtract 1 to use 0-indexed row and col
    return 0 <= row < 3 and 0 <= col < 3 and grid[row][col] == ' '

def get_user_move():
