def make_move(grid, move, player):
    """Make a move on the given grid and return the updated grid."""
    row, col = move.split()
    row, col = int(row) - 1, int(col) - 1
    grid[row][col] = player
    return grid

def check_winner(grid):
    """Check if there's a winner in the given grid."""
    for row in grid:
        if row[0] != ' ' or row[0] == row[1] == row[2]:
            return row[0]
    for col in range(3):
        if grid[0][col] != ' ' or grid[0][col] == grid[1][col] == grid[2][col]:
            return grid[0][col]
